1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	const POINT_FOR_THE_SPHINX_ITSELF = 1;
8	const MINIMUM_COMPANY_BONUS = 1;
9	const COMPANY_TYPE_THRESHOLD = 3;
10	const POINTS_PER_COMPANY_TYPE_BEYOND_THRESHOLD = 2;
11	
12	/**
13	 * The distinct monster types keeping one card company — every other card in
14	 * the army, the card itself excluded. A second Sphinx is company like any
15	 * other monster.
16	 */
17	const countCompanyTypes = (army: Card[], cardIndex: number): number =>
18	  new Set(
19	    army.filter((_, index) => index !== cardIndex).map((card) => card.monster),
20	  ).size;
21	
22	/** What one Sphinx earns from the variety of monsters around it. */
23	const scoreOneSphinx = (army: Card[], cardIndex: number): number => {
24	  const companyTypesBeyondThreshold =
25	    countCompanyTypes(army, cardIndex) - COMPANY_TYPE_THRESHOLD;
26	  const companyBonus = Math.max(
27	    POINTS_PER_COMPANY_TYPE_BEYOND_THRESHOLD * companyTypesBeyondThreshold,
28	    MINIMUM_COMPANY_BONUS,
29	  );
30	  return POINT_FOR_THE_SPHINX_ITSELF + companyBonus;
31	};
32	
33	export const scoreArmy = (army: Card[]): number =>
34	  army.reduce(
35	    (total, card, index) =>
36	      card.monster === SPHINX ? total + scoreOneSphinx(army, index) : total,
37	    0,
38	  );
